package ai.taskforge.domain;
import jakarta.persistence.*; import java.time.*; import java.util.*;
@Entity @Table(name="workflow_instances") public class WorkflowInstance { @Id @GeneratedValue private UUID id; @ManyToOne(optional=false) @JoinColumn(name="workflow_id") private Workflow workflow; @ManyToOne @JoinColumn(name="task_id") private Task task; @Enumerated(EnumType.STRING) @Column(nullable=false) private WorkflowInstanceStatus status=WorkflowInstanceStatus.ACTIVE; private int currentStepOrder; private Instant startedAt=Instant.now(); private Instant completedAt; protected WorkflowInstance(){} public WorkflowInstance(Workflow w,Task t){workflow=w;task=t;} public UUID getId(){return id;} public Workflow getWorkflow(){return workflow;} public Task getTask(){return task;} public WorkflowInstanceStatus getStatus(){return status;} public int getCurrentStepOrder(){return currentStepOrder;} public void moveTo(int order){currentStepOrder=order;} public void complete(){status=WorkflowInstanceStatus.COMPLETED;completedAt=Instant.now();} }
